appearances.css:
.app{display:flex;flex-direction:row;flex-wrap:wrap;align-items:stretch;gap:4px;padding:6px;border-radius:4px;font-size:9px}
.row{display:flex;flex-wrap:wrap;gap:4px 5px;margin:0;align-items:flex-end;border:1px solid var(--line,#344953);border-radius:4px;padding:4px 5px}
.row .control{flex:1 1 70px}
.row button{font-size:8.5px;padding:3px 6px;border-radius:3px;flex:0 0 auto}
.grid{display:grid;gap:3px 2px;border:1px solid var(--line,#344953);border-radius:4px;padding:4px 4px 3px;margin:0;grid-template-columns:repeat(4,minmax(0,1fr))}
.pads{grid-template-columns:repeat(5,minmax(0,1fr));gap:3px}
.pads button{min-height:0;height:24px;padding:1px 3px;font-size:8px;line-height:1.1;text-align:center;white-space:normal;border-radius:3px;display:flex;align-items:center;justify-content:center}
h3~.grid+.pads{grid-template-columns:repeat(16,minmax(0,1fr));gap:2px}
h3~.grid+.pads button{padding:1px 0;font-size:7.5px;white-space:nowrap}
h3{font-size:9.5px;margin:2px 0 0}
p{display:none}
canvas{width:1px!important;min-width:100%;height:28px!important;border-radius:3px}
.control{display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;align-items:start;gap:0;border:0;padding:0;min-width:0;border-radius:0}
.control>span:not(.kn){order:3;font-size:7.5px;text-align:center;line-height:1.1;max-width:100%;letter-spacing:-.02em}
.control>output{order:2;font-size:8px;line-height:1.1;text-align:center;white-space:nowrap}
.control>.kn{order:1;width:26px!important;height:26px!important;justify-self:center!important}
.control .kn svg{width:100%;height:100%}
.control>select{order:1;width:100%;font-size:8.5px;padding:3px 0;text-align:center;text-align-last:center;appearance:none;-webkit-appearance:none;border-radius:3px;cursor:pointer}
.app>*{flex:1 1 100%;min-width:0}
.app>:nth-child(1){order:1;flex:1 1 200px}
.app>:nth-child(3){order:2;flex:0 0 74px;grid-template-columns:minmax(0,1fr)}
.app>:nth-child(2){order:3}
.app>:nth-child(4){order:4}
.app>:nth-child(5){order:5}
.app>:nth-child(8){order:6}
.app>:nth-child(6){order:7;flex:4 1 240px}
.app>:nth-child(7){order:8;flex:1 1 56px;grid-template-columns:minmax(0,1fr)}
.app>:nth-child(9){order:9;flex:1 1 56px}
.app>:nth-child(10){order:10;flex:2 1 112px;grid-template-columns:repeat(2,minmax(0,1fr))}
.app>:nth-child(11){order:11}
.app>:nth-child(12){order:12}
.row .control{flex:1 1 60px}
.app>:nth-child(9) .control{width:100%}
.app>:nth-child(2) .control:nth-child(1){flex:0 1 44px}
.app>:nth-child(2) .control:nth-child(2){flex:2 1 120px}
.app>:nth-child(2) .control:nth-child(3){flex:1 1 84px}
.app>:nth-child(2) button{flex:0 1 auto;white-space:nowrap}
